CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at DATETIME NOT NULL);
CREATE TABLE users (id VARCHAR(32) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'customer', status VARCHAR(16) NOT NULL DEFAULT 'active', referral_code VARCHAR(32) NOT NULL UNIQUE, referred_by VARCHAR(32), created_at DATETIME NOT NULL);
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(32) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE reset_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(32) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE wallets (user_id VARCHAR(32) PRIMARY KEY, balance_pence BIGINT NOT NULL DEFAULT 0 CHECK(balance_pence>=0), reserved_pence BIGINT NOT NULL DEFAULT 0 CHECK(reserved_pence>=0 AND reserved_pence<=balance_pence), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE ledger (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,kind VARCHAR(32) NOT NULL,amount_pence BIGINT NOT NULL,balance_after_pence BIGINT NOT NULL,reserved_after_pence BIGINT NOT NULL DEFAULT 0,reference VARCHAR(160) NOT NULL UNIQUE,description TEXT NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX ledger_user_date ON ledger(user_id,created_at);
CREATE TABLE orders (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,provider VARCHAR(32) NOT NULL,provider_order_id VARCHAR(120),product VARCHAR(32) NOT NULL,service VARCHAR(120) NOT NULL,country VARCHAR(80),phone VARCHAR(40),sms_code VARCHAR(120),status VARCHAR(32) NOT NULL,price_pence BIGINT NOT NULL,price_tier VARCHAR(16) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash VARCHAR(64) NOT NULL,expires_at DATETIME,auto_renew INTEGER NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,idempotency_key),UNIQUE(provider,provider_order_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX orders_user_status ON orders(user_id,status);
CREATE TABLE payments (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,provider VARCHAR(32) NOT NULL,provider_reference VARCHAR(255) UNIQUE,amount_pence BIGINT NOT NULL,currency VARCHAR(3) NOT NULL DEFAULT 'GBP',status VARCHAR(32) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE api_keys (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,key_hash VARCHAR(64) NOT NULL UNIQUE,prefix VARCHAR(18) NOT NULL,last_used_at DATETIME,revoked_at DATETIME,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE pricing_snapshots (id VARCHAR(200) PRIMARY KEY,payload TEXT NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE settings (name VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE messages (id VARCHAR(32) PRIMARY KEY,order_id VARCHAR(32) NOT NULL,provider_message_id VARCHAR(120) NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL,UNIQUE(order_id,provider_message_id),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE inboxes (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,provider_id VARCHAR(120) UNIQUE,address VARCHAR(254),status VARCHAR(32) NOT NULL,price_pence BIGINT NOT NULL,expires_at DATETIME,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE smm_orders (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,provider_order_id VARCHAR(120) UNIQUE,service VARCHAR(120) NOT NULL,target TEXT NOT NULL,quantity INTEGER NOT NULL,price_pence BIGINT NOT NULL,status VARCHAR(32) NOT NULL,start_count INTEGER,remaining INTEGER,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE reward_claims (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,reward VARCHAR(80) NOT NULL,period VARCHAR(80) NOT NULL,amount_pence BIGINT NOT NULL,created_at DATETIME NOT NULL,UNIQUE(user_id,reward,period),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE announcements (id VARCHAR(32) PRIMARY KEY,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'announcement',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE support_tickets (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,issue_type VARCHAR(80) NOT NULL,payment_reference VARCHAR(255) NOT NULL,description TEXT NOT NULL,attachment VARCHAR(80) NOT NULL,mime VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending_email',created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_log (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32),action VARCHAR(100) NOT NULL,details TEXT NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE rate_limits (id VARCHAR(64) PRIMARY KEY,hits INTEGER NOT NULL,expires_at DATETIME NOT NULL);
CREATE TABLE job_runs (id VARCHAR(32) PRIMARY KEY,name VARCHAR(80) NOT NULL,status VARCHAR(32) NOT NULL,summary TEXT,started_at DATETIME NOT NULL,finished_at DATETIME);
